import { execFileSync } from 'node:child_process';
import {
  cpSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  renameSync,
  rmSync,
  symlinkSync
} from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import {
  join,
  sep
} from 'node:path';
import process from 'node:process';
import {
  createContext,
  runInContext
} from 'node:vm';
import {
  afterAll,
  beforeAll,
  describe,
  expect,
  it
} from 'vitest';

interface BundlerCase {
  readonly bundler: string;
  readonly isDevelopment: boolean;
}

interface FixtureCommand {
  readonly callback: () => unknown;
  readonly id: string;
  readonly name: string;
}

interface FixturePlugin {
  readonly commands: FixtureCommand[];
  onload: () => Promise<void>;
}

interface LoadedModule {
  exports: unknown;
}

interface LoadedPlugin {
  readonly plugin: FixturePlugin;
  readonly PluginBaseClass: abstract new () => unknown;
}

interface PluginExports {
  readonly default?: unknown;
}

type PluginLoadFunction = (require: (moduleId: string) => unknown, module: LoadedModule, exports: unknown) => void;

const REPO_ROOT = join(import.meta.dirname, '../..');
const FIXTURE_SOURCE_FOLDER = join(REPO_ROOT, 'test-fixtures/obsidian-plugin');
const BUILD_SCRIPT = join(REPO_ROOT, 'scripts/helpers/build-bundler-fixture.ts');
const JITI_CLI = join(REPO_ROOT, 'node_modules/jiti/lib/jiti-cli.mjs');

const BUILD_TIMEOUT_IN_MILLISECONDS = 180_000;

const BUNDLER_CASES: readonly BundlerCase[] = [
  { bundler: 'esbuild', isDevelopment: false },
  { bundler: 'parcel', isDevelopment: false },
  { bundler: 'rollup', isDevelopment: false },
  { bundler: 'vite', isDevelopment: false },
  { bundler: 'webpack', isDevelopment: false },
  // Esbuild's and parcel's `dev()` always watch, so only the adapters with a `mode` option build once in development.
  { bundler: 'rollup', isDevelopment: true },
  { bundler: 'vite', isDevelopment: true },
  { bundler: 'webpack', isDevelopment: true }
];

// Each case writes the same fixture's `dist` folder; the cases of one file run one after another.
describe('every bundler adapter builds a loadable Obsidian plugin', () => {
  let fixtureFolder = '';

  // The fixture is built in a copy outside the repository: every adapter takes the nearest `package.json`
  // for the project root, and the library build deletes every nested `package.json` in the repository, so
  // the fixture keeps its own under another name. Its `node_modules` links to this repository's.
  beforeAll(() => {
    fixtureFolder = mkdtempSync(join(tmpdir(), 'obsidian-dev-toolkit-bundler-fixture-'));
    cpSync(FIXTURE_SOURCE_FOLDER, fixtureFolder, { recursive: true });
    renameSync(join(fixtureFolder, 'fixture-package.json'), join(fixtureFolder, 'package.json'));
    symlinkSync(join(REPO_ROOT, 'node_modules'), join(fixtureFolder, 'node_modules'), 'junction');
  });

  afterAll(() => {
    if (fixtureFolder) {
      rmSync(fixtureFolder, { force: true, recursive: true });
    }
  });

  it.each(BUNDLER_CASES)('$bundler (development: $isDevelopment)', async ({ bundler, isDevelopment }) => {
    const env = { ...process.env };
    // A development build deploys into this vault when it is set, and a test must not touch a real vault.
    delete env['OBSIDIAN_CONFIG_FOLDER'];
    execFileSync(process.execPath, [JITI_CLI, BUILD_SCRIPT, bundler, ...isDevelopment ? ['development'] : []], {
      cwd: fixtureFolder,
      env,
      stdio: 'pipe'
    });

    const distFolder = join(fixtureFolder, isDevelopment ? 'dist/dev' : 'dist/build');

    // An Obsidian release ships these files and nothing else, so a sibling chunk or an extracted license
    // file would be missing from the installed plugin. A development build adds HotReload's marker.
    expect(readdirSync(distFolder).sort()).toEqual([...isDevelopment ? ['.hotreload'] : [], 'main.js', 'manifest.json', 'styles.css']);
    expect(readFileSync(join(distFolder, 'styles.css'), 'utf-8')).toContain('bundler fixture');

    const mainJs = readFileSync(join(distFolder, 'main.js'), 'utf-8');
    expect(mainJs).toMatch(new RegExp(String.raw`^/\*\nTHIS IS A GENERATED/BUNDLED FILE BY ${bundler.toUpperCase()}\n`, 'u'));
    expect(mainJs.includes('sourceMappingURL=data:')).toBe(isDevelopment);

    const { plugin, PluginBaseClass } = loadPlugin(mainJs);
    expect(plugin).toBeInstanceOf(PluginBaseClass);
    await plugin.onload();

    expect(plugin.commands).toHaveLength(1);
    expect(plugin.commands[0]?.name).toBe('Hello, bundler');
    expect(plugin.commands[0]?.callback()).toBe(sep);
  }, BUILD_TIMEOUT_IN_MILLISECONDS);
});

/**
 * Loads a built `main.js` the way Obsidian's own plugin loader does: as the body of
 * `function (require, module, exports)`, with a `module` that is nothing but `{ exports }`, taking the
 * plugin class from `module.exports.default` or `module.exports`, then constructing it.
 *
 * @param mainJs - The bundle's source.
 * @returns The constructed plugin and the `Plugin` class it must extend.
 */
function loadPlugin(mainJs: string): LoadedPlugin {
  class Plugin {
    public readonly commands: FixtureCommand[] = [];

    public addCommand(command: FixtureCommand): void {
      this.commands.push(command);
    }
  }

  const nodeRequire = createRequire(import.meta.url);
  function requireLikeObsidian(moduleId: string): unknown {
    if (moduleId === 'obsidian') {
      return { Plugin };
    }
    if (moduleId === 'node:path' || moduleId === 'path') {
      return nodeRequire(moduleId);
    }
    throw new Error(`The bundle required '${moduleId}', which an installed plugin cannot reach.`);
  }

  const loadedModule: LoadedModule = { exports: {} };
  // The esbuild banner reads `app.isMobile` to tell desktop from mobile.
  const context = createContext({ app: { isMobile: false } });
  const loadFunction = runInContext(`(function anonymous(require,module,exports){${mainJs}\n})`, context) as PluginLoadFunction;
  loadFunction(requireLikeObsidian, loadedModule, loadedModule.exports);

  const pluginExports = loadedModule.exports as PluginExports;
  const PluginClass = (pluginExports.default ?? pluginExports) as new () => FixturePlugin;
  return { plugin: new PluginClass(), PluginBaseClass: Plugin };
}
